"""ND Anti-Hang balanced always-on hook kernel.

Small cross-cutting runtime. It does not own task decomposition, domain routing,
memory lifecycle, provider route strategy, or user-visible message rendering.
"""
from __future__ import annotations

import math

NONTERMINAL = {"ACCEPTED", "SUBMITTED", "QUEUED", "PENDING", "RUNNING"}
RUNNABLE_STATES = {"", "READY", "RUNNABLE", "PLANNED", "PREP", "VERIFY", "RESEARCH", "RECOVERY", "INTEGRATION"}

HOOK_EVENTS = {
    "TASK_ENTRY",
    "BEFORE_ACTION",
    "AFTER_ACTION",
    "AFTER_MATERIAL_RETURN",
    "PRESSURE",
    "BEFORE_USER_RETURN",
    "USER_STOP",
}

PRESSURE_SIGNALS = {
    "TRANCHE_OVERSIZED",
    "TOOL_CALL_CEILING",
    "RESULT_TRUNCATION",
    "BROAD_FANOUT",
    "SCOPE_EXPANSION",
    "LONG_FOREGROUND_RETURN",
    "CUMULATIVE_OUTER_TURN",
}


def replay_gate(*, consequential: bool, provider_state: str | None = None, authorized: bool = False):
    """Prevent duplicate consequential effects after ambiguous returns."""
    if not consequential:
        return "SAFE_READ_RETRY_OR_ALTERNATE"
    state = (provider_state or "UNKNOWN").upper()
    if state == "PRESENT":
        return "ACCEPT_EFFECT_NO_REPLAY"
    if state == "ABSENT":
        return "RETRY_ALLOWED_AFTER_RECONCILIATION" if authorized else "BLOCKED_AUTHORITY"
    return "OUTCOME_UNKNOWN_RECONCILE"


def runnable_scan(frontiers=None, pending_effect_ids=None):
    """Select the highest-value independent safe materially useful frontier."""
    pending = set(pending_effect_ids or [])
    runnable = []
    for frontier in frontiers or []:
        deps = set(frontier.get("depends_on_effect_ids") or [])
        state = str(frontier.get("state") or "").upper()
        if deps & pending:
            continue
        if not frontier.get("safe", True) or not frontier.get("materially_useful", False):
            continue
        if state not in RUNNABLE_STATES:
            continue
        runnable.append(frontier)

    runnable.sort(key=lambda x: (x.get("priority", 0), x.get("value", 0)), reverse=True)
    if runnable:
        return {
            "verdict": "AUTO_CONTINUE",
            "selected_frontier": runnable[0].get("id"),
            "runnable_frontiers": [x.get("id") for x in runnable],
            "scan_complete": True,
        }
    return {"verdict": "NO_RUNNABLE", "runnable_frontiers": [], "scan_complete": True}


def effect_transition(
    *,
    status: str | None,
    effect_id=None,
    frontier_id=None,
    outcome_unknown=False,
    frontiers=None,
    pending_effect_ids=None,
    result_ready=False,
    result_ref=None,
    effect_record=None,
):
    """Map provider/effect observation to local wait/reconcile/continue semantics."""
    if isinstance(effect_record, dict) and effect_record.get("stop_at") is not None:
        return {"verdict": "RETURN_USER_STOP", "freeze_new_ops": True,
                "remote_cancel_assumed": False, "late_result_ignored": True}
    if outcome_unknown:
        return {
            "state": "OUTCOME_UNKNOWN",
            "verdict": "RECONCILE_EFFECT",
            "effect_id": effect_id,
            "frontier_id": frontier_id,
            "allow_new_conflicting_effect": False,
        }

    if result_ready and result_ref and effect_id:
        return {
            "state": "RESULT_READY",
            "verdict": "REENTER_ROOT",
            "effect_id": effect_id,
            "result_ref": result_ref,
            "remote_status": (status or "").upper(),
            "requires_root_reentry": True,
            "wait_for_nonessential_cleanup": False,
            "replay_allowed": False,
        }

    status = (status or "").upper()
    if status in NONTERMINAL:
        scan = runnable_scan(frontiers, pending_effect_ids or ([effect_id] if effect_id else []))
        if scan["verdict"] == "AUTO_CONTINUE":
            return {
                "state": "EFFECT_WAIT",
                "frontier_state": "FRONTIER_BLOCKED",
                "verdict": "AUTO_CONTINUE",
                "selected_frontier": scan["selected_frontier"],
                "runnable_frontiers": scan["runnable_frontiers"],
                "effect_id": effect_id,
                "frontier_id": frontier_id,
                "replay_allowed": False,
                "requires_root_reentry": True,
            }
        return {
            "state": "EFFECT_WAIT",
            "frontier_state": "FRONTIER_BLOCKED",
            "verdict": "REENTER_ROOT",
            "effect_id": effect_id,
            "frontier_id": frontier_id,
            "replay_allowed": False,
            "requires_root_scan": True,
        }

    return {
        "state": "ACTIVE",
        "verdict": "REENTER_ROOT",
        "status": status,
        "requires_root_reentry": True,
    }


def record_observation(*, effect_record, effect_id, generation, observation_id, kind, evidence_ref):
    """Record one actual wake/follow-up in the existing work-local effect record.

    The effect owner persists this record; no observer, timer or delivery mechanism
    is created here. Reusing a boolean or an old token cannot mint eligibility.
    """
    if not isinstance(effect_record, dict) or (
        effect_record.get("effect_id") != effect_id or effect_record.get("generation") != generation
    ):
        return "STALE_OBSERVATION"
    if effect_record.get("stop_at") is not None:
        return "STOPPED_OBSERVATION_IGNORED"
    if (not isinstance(observation_id, str) or not observation_id or
            not isinstance(evidence_ref, str) or not evidence_ref or
            kind not in {"SUBMIT_ACK", "MATERIAL_WAKE", "RECOVERY_RECEIPT"}):
        return "INVALID_OBSERVATION"
    observations = effect_record.setdefault("observations", {})
    if observation_id in observations:
        return "DUPLICATE_OBSERVATION"
    observations[observation_id] = {
        "effect_id": effect_id, "generation": generation, "kind": kind,
        "evidence_ref": evidence_ref, "consumed_by": None,
    }
    return "OBSERVATION_RECORDED"


def reconcile_eligibility(
    *, status: str | None, effect_record=None, effect_id=None, generation=None,
    observation_id=None, action_id=None, consume=False,
    material_wake=False, immediate_followup=False,
):
    """One status read consumes one effect/generation-bound observation.

    Legacy booleans are accepted as inputs but never authorize an external read.
    """
    if not isinstance(effect_record, dict) or effect_record.get("stop_at") is not None:
        return "PARK_EFFECT_NO_POLL"
    if effect_record.get("effect_id") != effect_id or effect_record.get("generation") != generation:
        return "PARK_EFFECT_NO_POLL"
    observation = effect_record.get("observations", {}).get(observation_id)
    if not observation or observation.get("consumed_by") is not None or (
        observation.get("effect_id") != effect_id or observation.get("generation") != generation
    ):
        return "PARK_EFFECT_NO_POLL"
    if consume:
        if not action_id:
            return "PARK_EFFECT_NO_POLL"
        observation["consumed_by"] = action_id
    return "RECONCILE_EFFECT"


def execution_admission(execution_profile=None, *, execution_scope="HOST_CONTROLLED"):
    """Scope admission to the boundary the caller actually controls.

    Existing host-controlled calls remain usable without claiming a qualified
    host deadline. Owned/qualified boundaries require their enforced profile;
    explicit opaque-risk routes are recovered. Evidence is not enforcement.
    """
    denied = {"verdict": "RECOVER_EXECUTION_ROUTE", "allow_action": False,
              "requires_root_reentry": True, "reason": "EXECUTION_BOUNDARY_UNQUALIFIED"}
    scope = str(execution_scope or "HOST_CONTROLLED").upper()
    if scope not in {"HOST_CONTROLLED", "ND_OWNED", "QUALIFIED_BOUNDARY"}:
        return denied
    host = {"verdict": "ALLOW_ACTION", "allow_action": True,
            "execution_kind": "HOST_CONTROLLED", "deadline_owner": None,
            "host_deadline_qualified": False}
    if execution_profile is None and scope == "HOST_CONTROLLED":
        return host
    if not isinstance(execution_profile, dict):
        return denied
    profile = execution_profile
    if profile.get("kind") == "HOST_CONTROLLED":
        return host if scope == "HOST_CONTROLLED" and profile.get("owner") == "HOST_CONTROLLED" else denied
    if scope != "HOST_CONTROLLED" and profile.get("owner") != scope:
        return denied
    deadline = profile.get("request_deadline_seconds")
    if isinstance(deadline, bool) or not isinstance(deadline, (int, float)) or not math.isfinite(deadline) or deadline <= 0:
        return denied
    if not profile.get("boundary_id"):
        return denied
    owned = profile.get("owner") == "ND_OWNED" and profile.get("enforcement") == "OWNED_DETACHED_WAIT"
    qualified = (profile.get("owner") == "QUALIFIED_BOUNDARY" and
                 profile.get("enforcement") == "QUALIFIED_REQUEST_DEADLINE" and
                 bool(profile.get("qualification_ref")))
    if not (owned or qualified):
        return denied
    if profile.get("kind") == "DURABLE_ASYNC":
        if profile.get("return_contract") != "ACK_WITH_DURABLE_EFFECT_ID":
            return denied
    elif profile.get("kind") != "BOUNDED_SYNC":
        return denied
    return {"verdict": "ALLOW_ACTION", "allow_action": True,
            "execution_kind": profile["kind"], "deadline_owner": profile["boundary_id"]}


def pressure_policy(*, pressured=False, signals=None):
    """Pressure changes execution shape; it never ends the global task."""
    observed = {str(x).upper() for x in (signals or [])}
    active = pressured or bool(observed & PRESSURE_SIGNALS)
    return "NARROW_COMPACT" if active else "NORMAL_BOUNDED"


def return_gate(
    *,
    task_complete=False,
    explicit_user_stop=False,
    true_gate=False,
    pending_required_external=False,
    scan_complete=False,
    runnable_work=False,
    reconcile_due=False,
    safe_acceleration_or_recovery=False,
    wake_mechanism_available=False,
):
    """The only Anti-Hang global-return gate. Default is continue."""
    if explicit_user_stop:
        return "RETURN_USER_STOP"
    if task_complete:
        return "RETURN_COMPLETED"
    if true_gate:
        return "RETURN_TRUE_GATE"

    if pending_required_external:
        if not scan_complete:
            return "AUTO_CONTINUE_REASSESS_FRONTS"
        if runnable_work or reconcile_due or safe_acceleration_or_recovery:
            return "AUTO_CONTINUE"
        if wake_mechanism_available:
            return "ACTIVATE_WAKE_AND_CONTINUE"
        return "GLOBAL_WAIT_EXTERNAL"

    return "AUTO_CONTINUE"


def before_action_gate(
    *,
    explicit_user_stop=False,
    consequential=False,
    provider_state=None,
    replay_intent=False,
    authorized=False,
    effect_identity=None,
    recovery_boundary_preserved=False,
    action_kind=None,
    effect_status=None,
    material_wake=False,
    immediate_followup=False,
    composite=False,
    consequential_effect_count=0,
    mixes_prepare_write_readback=False,
    atomic_provider_transaction=False,
    broad_fanout=False,
    pressured=False,
    pressure_signals=None,
    execution_profile=None,
    execution_scope="HOST_CONTROLLED",
    effect_record=None,
    effect_generation=None,
    observation_id=None,
    action_id=None,
):
    """Preflight effect/replay/composite safety before a tool/provider operation opens."""
    if explicit_user_stop or (isinstance(effect_record, dict) and effect_record.get("stop_at") is not None):
        return {"verdict": "RETURN_USER_STOP", "allow_action": False, "freeze_new_ops": True}

    if replay_intent and consequential:
        replay = replay_gate(
            consequential=True,
            provider_state=provider_state,
            authorized=authorized,
        )
        if replay in {"OUTCOME_UNKNOWN_RECONCILE", "BLOCKED_AUTHORITY"}:
            return {"verdict": replay, "allow_action": False}
        if replay == "ACCEPT_EFFECT_NO_REPLAY":
            return {"verdict": replay, "allow_action": False}

    if consequential and not (effect_identity or recovery_boundary_preserved):
        return {
            "verdict": "PREPARE_RECOVERY_BOUNDARY",
            "allow_action": False,
            "reason": "CONSEQUENTIAL_EFFECT_NEEDS_IDENTITY_OR_RECOVERABLE_PRECALL_BOUNDARY",
        }

    if composite:
        if mixes_prepare_write_readback:
            return {
                "verdict": "ISOLATE_CONSEQUENTIAL_EFFECT",
                "allow_action": False,
                "reason": "PREPARE_WRITE_READBACK_MUST_NOT_SHARE_OPAQUE_COMPOSITE",
            }
        if consequential_effect_count > 1 and not atomic_provider_transaction:
            return {
                "verdict": "ISOLATE_CONSEQUENTIAL_EFFECT",
                "allow_action": False,
                "reason": "MULTIPLE_CONSEQUENTIAL_EFFECTS_REQUIRE_ISOLATION",
            }
        if broad_fanout and pressure_policy(
            pressured=pressured,
            signals=pressure_signals,
        ) == "NARROW_COMPACT":
            return {
                "verdict": "NARROW_ACTION",
                "allow_action": False,
                "reason": "PRESSURED_BROAD_FANOUT",
            }

    admission = execution_admission(execution_profile, execution_scope=execution_scope)
    if not admission["allow_action"]:
        return admission

    if str(action_kind or "").upper() in {"STATUS", "STATUS_RECONCILE", "POLL"}:
        reconcile = reconcile_eligibility(
            status=effect_status, effect_record=effect_record, effect_id=effect_identity,
            generation=effect_generation, observation_id=observation_id,
            action_id=action_id, consume=True,
        )
        return {**admission, "verdict": reconcile, "allow_action": reconcile == "RECONCILE_EFFECT"}
    return admission


def hook(event: str, **ctx):
    """Always-on dispatcher. Preferred production Anti-Hang interface."""
    event = str(event or "").upper()
    if event not in HOOK_EVENTS:
        return {"verdict": "INVALID_HOOK_EVENT", "event": event, "auto_continue": False}

    effect_record = ctx.get("effect_record")
    if isinstance(effect_record, dict) and effect_record.get("stop_at") is not None:
        ctx["explicit_user_stop"] = True

    if event == "TASK_ENTRY":
        if ctx.get("explicit_user_stop"):
            return {"verdict": "RETURN_USER_STOP", "hook_active": True, "freeze_new_ops": True}
        return {"verdict": "AUTO_CONTINUE", "hook_active": True, "state": "ACTIVE"}

    if event == "USER_STOP":
        return {
            "verdict": "RETURN_USER_STOP",
            "freeze_new_ops": True,
            "remote_cancel_assumed": False,
            "preserve_verified_continuation": True,
        }

    if event == "BEFORE_ACTION":
        return before_action_gate(**ctx)

    if event == "AFTER_ACTION":
        if ctx.get("explicit_user_stop"):
            return {
                "verdict": "RETURN_USER_STOP",
                "freeze_new_ops": True,
                "remote_cancel_assumed": False,
                "preserve_verified_continuation": True,
            }
        if ctx.get("route_failure"):
            return {
                "verdict": "REENTER_ROOT_RECOVERY",
                "requires_root_reentry": True,
                "retry_same_route": False,
            }
        return effect_transition(
            status=ctx.get("status"),
            effect_id=ctx.get("effect_id"),
            frontier_id=ctx.get("frontier_id"),
            outcome_unknown=ctx.get("outcome_unknown", False),
            frontiers=ctx.get("frontiers"),
            pending_effect_ids=ctx.get("pending_effect_ids"),
            result_ready=ctx.get("result_ready", False),
            result_ref=ctx.get("result_ref"),
            effect_record=effect_record,
        )

    if event == "AFTER_MATERIAL_RETURN":
        if ctx.get("explicit_user_stop"):
            return {
                "verdict": "RETURN_USER_STOP",
                "freeze_new_ops": True,
                "remote_cancel_assumed": False,
                "preserve_verified_continuation": True,
            }
        if ctx.get("outcome_unknown"):
            return {"verdict": "RECONCILE_EFFECT", "requires_root_reentry": True}

        mode = pressure_policy(
            pressured=ctx.get("pressured", False),
            signals=ctx.get("pressure_signals"),
        )
        if mode == "NARROW_COMPACT":
            return {
                "verdict": "ROTATE_SAFE_CYCLE_AUTO_CONTINUE",
                "requires_root_reentry": True,
                "compact_continuation": True,
                "reconcile_pending_after_material_wake": bool(ctx.get("pending_effects")),
            }
        return {
            "verdict": "REENTER_ROOT",
            "requires_root_reentry": True,
            "reconcile_pending_after_material_wake": bool(ctx.get("pending_effects")),
        }

    if event == "PRESSURE":
        if ctx.get("explicit_user_stop"):
            return {
                "verdict": "RETURN_USER_STOP",
                "freeze_new_ops": True,
                "remote_cancel_assumed": False,
                "preserve_verified_continuation": True,
                "auto_continue": False,
            }
        mode = pressure_policy(
            pressured=ctx.get("pressured", False),
            signals=ctx.get("signals"),
        )
        if mode == "NARROW_COMPACT":
            return {
                "verdict": "ROTATE_SAFE_CYCLE_AUTO_CONTINUE",
                "execution_shape": "NARROW_COMPACT",
                "user_visible_return": False,
            }
        return {"verdict": "AUTO_CONTINUE", "execution_shape": "NORMAL_BOUNDED"}

    if event == "BEFORE_USER_RETURN":
        verdict = return_gate(
            task_complete=ctx.get("task_complete", False),
            explicit_user_stop=ctx.get("explicit_user_stop", False),
            true_gate=ctx.get("true_gate", False),
            pending_required_external=ctx.get("pending_required_external", False),
            scan_complete=ctx.get("scan_complete", False),
            runnable_work=ctx.get("runnable_work", False),
            reconcile_due=ctx.get("reconcile_due", False),
            safe_acceleration_or_recovery=ctx.get("safe_acceleration_or_recovery", False),
            wake_mechanism_available=ctx.get("wake_mechanism_available", False),
        )
        allowed = verdict in {
            "RETURN_USER_STOP",
            "RETURN_COMPLETED",
            "RETURN_TRUE_GATE",
            "GLOBAL_WAIT_EXTERNAL",
        }
        return {
            "verdict": verdict,
            "user_visible_return": allowed,
            "auto_continue": not allowed,
        }

    return {"verdict": "AUTO_CONTINUE"}
